DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia de la Diabetes$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia de la Diabetes$t$;
    RETURN;
  END IF;

  -- 01. Tipos de insulina y perfiles de acción: rápidas, regular, NPH, basales y premezcladas
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La insulina que no era para la hora de la comida","texto":"Un paciente con diabetes tipo 1 usa insulina glargina antes del desayuno y cree que también cubre la comida. A las dos horas tiene una hiperglucemia marcada; luego, por miedo, se aplica una dosis extra de glargina y termina con hipoglucemia nocturna. El problema no era la dosis: era el perfil de acción. Conocer qué insulina cubre qué momento evita errores graves."},"objetivos":["Clasificar las insulinas por perfil de acción y uso clínico.","Diferenciar insulina rápida, regular, NPH, basal y premezclada.","Relacionar el perfil con el esquema basal-bolo y las comidas.","Reconocer los errores de uso más frecuentes en la dispensación."],"conceptos":[{"icono":"Syringe","termino":"Insulina basal","definicion":"Insulina de acción intermedia o prolongada que cubre las necesidades entre comidas y durante la noche."},{"icono":"Timer","termino":"Insulina rápida","definicion":"Análogo de acción rápida que se aplica antes de comer para cubrir la glucosa posprandial."},{"icono":"Activity","termino":"Insulina regular","definicion":"Insulina humana de acción corta; se aplica 30 minutos antes de la comida y tiene un pico más tardío."},{"icono":"Layers","termino":"Premezclada","definicion":"Combinación de insulina basal y rápida en una sola aplicación; limita la flexibilidad de horarios."}],"secciones":[{"titulo":"El perfil manda","parrafos":["Cada insulina tiene un inicio, un pico y una duración distintos. Las rápidas (lispro, aspart, glulisina) empiezan en 10 a 20 minutos, tienen un pico alrededor de una hora y duran 3 a 5 horas. Se aplican antes de comer. La regular empieza en 30 minutos, tiene un pico más tardío y dura 5 a 8 horas; exige planear la comida.","Las basales cubren las necesidades de fondo. La NPH tiene un pico y una duración intermedia, por lo que puede causar hipoglucemia nocturna. La glargina, la detemir y la degludec tienen perfiles más planos y prolongados. Las premezcladas combinan una basal con una rápida, pero obligan a horarios fijos y dificultan el ajuste fino."]},{"titulo":"Cómo se elige","parrafos":["El esquema basal-bolo es el más fisiológico: una basal para el fondo y una rápida para cada comida. Se usa en diabetes tipo 1 y en diabetes tipo 2 con necesidad de insulina prandial. La insulina basal sola puede ser suficiente al inicio de la diabetes tipo 2. Las premezcladas se reservan para pacientes con horarios estables y dificultad para múltiples inyecciones.","La elección depende de la glucosa, la alimentación, la actividad, la habilidad para contar carbohidratos, el costo y la preferencia. No se debe cambiar una insulina por otra sin ajustar el esquema y educar. La equivalencia entre insulinas no es automática."]},{"titulo":"Errores frecuentes","parrafos":["Confundir la basal con la rápida es un error grave. Aplicar una basal antes de comer no cubre el pico posprandial; aplicar una rápida como basal produce hipoglucemia. Otra confusión frecuente es usar una pluma de insulina rápida para la noche o mezclar insulinas sin la técnica adecuada.","La educación debe incluir el nombre, el aspecto, la hora, la dosis y el sitio de cada insulina. El QF puede revisar las plumas, las etiquetas y el horario. Si el paciente no distingue los colores o no sabe leer, se usan estrategias de identificación y apoyo del cuidador."]}],"errores":[{"error":"Usar basal para cubrir comidas.","correccion":"La basal cubre el fondo; la rápida cubre el pico posprandial."},{"error":"Aplicar regular y comer de inmediato.","correccion":"La regular debe aplicarse unos 30 minutos antes de comer."},{"error":"Cambiar de insulina sin ajustar dosis.","correccion":"Las insulinas no son intercambiables mg a mg; se ajusta y se educa."}],"comprueba":[{"pregunta":"¿Qué insulina cubre la comida?","respuesta":"La rápida o la regular, según el esquema."},{"pregunta":"¿Qué insulina cubre el fondo?","respuesta":"La basal: NPH, glargina, detemir o degludec."},{"pregunta":"¿Cuál es el riesgo de una premezclada?","respuesta":"Menos flexibilidad y mayor riesgo de hipoglucemia si se cambian horarios."}],"resumen":["Cada insulina tiene un **perfil de acción** distinto.","La basal no cubre las comidas.","El esquema basal-bolo es el más fisiológico.","La educación sobre nombre, hora y sitio evita errores."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Insulin, medicines, and other diabetes treatments.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"}],"imagenes":[{"ubicacion":"Sección de perfiles","descripcion":"Gráfica de curvas de acción de insulina rápida, regular, NPH y glargina, con inicio, pico y duración.","alt":"Perfiles de acción de las insulinas"}],"keywords":["tipos de insulina","insulina rápida regular nph","insulina basal","insulina premezclada","perfil de acción insulina","esquema basal bolo","curso insulinoterapia diabetes"],"mapa":{"centro":"Tipos de insulina","ramas":[{"titulo":"Rápidas","icono":"Timer","nodos":["Lispro","Aspart","Glulisina","Antes de comer"]},{"titulo":"Regular","icono":"Activity","nodos":["Humana","30 minutos antes","Pico tardío"]},{"titulo":"Basales","icono":"Syringe","nodos":["NPH","Glargina","Detemir","Degludec"]},{"titulo":"Premezcladas","icono":"Layers","nodos":["70/30","75/25","Horarios fijos"]}]},"proceso":{"titulo":"Cómo revisar un esquema de insulina","intro":"","pasos":[{"titulo":"Identificar cada insulina","detalle":"Nombre, tipo, concentración y hora de aplicación.","icono":"Syringe","evidencia":"Lista de medicamentos."},{"titulo":"Relacionar con comidas","detalle":"Qué insulina cubre cada comida y la basal.","icono":"CalendarClock","evidencia":"Horario."},{"titulo":"Revisar glucometrías","detalle":"Ayunas, posprandial y nocturna.","icono":"LineChart","evidencia":"Registro."},{"titulo":"Detectar errores","detalle":"Confusión de plumas, dosis u horarios.","icono":"AlertTriangle","evidencia":"Entrevista."},{"titulo":"Educar","detalle":"Nombre, hora, sitio, conservación y qué hacer si olvida.","icono":"Users","evidencia":"Educación."}]},"caso":{"titulo":"Glargina antes de comer","contexto":"Paciente con diabetes tipo 1 usa glargina 20 UI en la mañana y no usa insulina rápida. Glucosa posprandial 320 mg/dL y HbA1c 9,2 %.","pregunta":"¿Cuál es el problema principal?","opciones":[{"texto":"La dosis de glargina es demasiado baja.","correcta":false,"retro":"La glargina es basal y no cubre el pico de la comida. Aumentarla puede causar hipoglucemia en ayunas sin resolver la posprandial."},{"texto":"Falta insulina rápida para las comidas; el esquema no es basal-bolo.","correcta":true,"retro":"La diabetes tipo 1 requiere insulina prandial. La basal no sustituye la rápida."},{"texto":"Debe cambiar a una premezclada sin educación.","correcta":false,"retro":"El cambio no resuelve el problema si no se ajusta el esquema y se educa."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Tipos de insulina y perfiles de acción: rápidas, regular, NPH, basales y premezcladas$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Tipos de insulina y perfiles de acción: rápidas, regular, NPH, basales y premezcladas$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Inicio y titulación de insulina basal en DM2 y combinación con agonistas GLP-1
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La insulina que se quedó en 10 unidades","texto":"Un paciente con diabetes tipo 2 inicia insulina basal 10 UI y sigue con HbA1c de 9 % seis meses después porque nadie tituló la dosis. La insulina basal no es “10 unidades y listo”: se ajusta con las glucometrías de ayuno. La inercia con la insulina es tan frecuente como el miedo a la hipoglucemia."},"objetivos":["Iniciar insulina basal en diabetes tipo 2 con criterios claros.","Titular la dosis con glucometrías de ayuno.","Combinar insulina basal con agonistas GLP-1 de forma segura.","Reconocer y prevenir la hipoglucemia durante la titulación."],"conceptos":[{"icono":"Syringe","termino":"Insulina basal","definicion":"Insulina de acción prolongada que controla la glucosa en ayunas y entre comidas."},{"icono":"Target","termino":"Titulación","definicion":"Ajuste de la dosis según la glucosa de ayuno, con aumentos graduales y seguimiento."},{"icono":"Layers","termino":"GLP-1 + basal","definicion":"Combinación que mejora la glucosa y el peso con menor riesgo de hipoglucemia que la insulina intensiva."},{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Riesgo principal de la insulinoterapia; se previene con educación y ajuste cuidadoso."}],"secciones":[{"titulo":"Cuándo iniciar insulina basal","parrafos":["La insulina basal se indica cuando la HbA1c está muy por encima de la meta, hay síntomas de catabolismo, hiperglucemia grave o no se alcanza el control con otros fármacos. En diabetes tipo 2, puede iniciarse con 10 UI al día o 0,1 a 0,2 UI/kg, según el peso y el riesgo de hipoglucemia. La dosis se ajusta con la glucosa de ayuno.","La educación es esencial: técnica, conservación, horario, hipoglucemia y qué hacer si se olvida una dosis. La insulina no debe verse como un fracaso, sino como una herramienta cuando la función beta ya no es suficiente."]},{"titulo":"Cómo titular","parrafos":["Se mide la glucosa de ayuno y se ajusta la dosis cada tres días. Un esquema frecuente es aumentar 2 UI si la glucosa está por encima de la meta, mantener si está en rango y reducir si hay hipoglucemia. La titulación debe ser individualizada y acompañada de registro.","La combinación con agonistas GLP-1 puede mejorar la HbA1c, reducir el peso y disminuir la dosis de insulina. También reduce el riesgo de hipoglucemia en comparación con la insulina intensiva. La titulación del GLP-1 es gradual y puede reducir el apetito; se ajusta la insulina si es necesario."]},{"titulo":"Seguridad y adherencia","parrafos":["La hipoglucemia es el efecto adverso más importante. Se educa al paciente y al cuidador sobre síntomas, tratamiento con la regla de los 15 y glucagón. Se revisan los horarios de comida, el ejercicio y el alcohol. La técnica de inyección y la rotación de sitios también afectan la absorción.","La inercia terapéutica es un problema real. Un paciente con HbA1c alta y dosis de insulina sin ajustar durante meses necesita una revisión. El QF puede identificar la falta de titulación y proponer un plan al equipo tratante."]}],"errores":[{"error":"Iniciar insulina y no titular.","correccion":"La dosis se ajusta según la glucosa de ayuno."},{"error":"Titular con una sola glucometría.","correccion":"Se usan varios registros y se revisan patrones."},{"error":"No educar sobre hipoglucemia.","correccion":"La educación es obligatoria antes de iniciar insulina."}],"comprueba":[{"pregunta":"¿Con qué se titula la insulina basal?","respuesta":"Con la glucosa de ayuno y un registro de varias mediciones."},{"pregunta":"¿Qué combinación reduce el riesgo de hipoglucemia?","respuesta":"Insulina basal con agonista GLP-1, con ajuste adecuado."},{"pregunta":"¿Qué se debe educar antes de iniciar?","respuesta":"Técnica, conservación, horario, hipoglucemia y qué hacer si olvida una dosis."}],"resumen":["La insulina basal se inicia con **dosis baja** y se titula.","La **glucosa de ayuno** guía el ajuste.","La combinación con **GLP-1** puede reducir la dosis y la hipoglucemia.","La educación y el seguimiento evitan la inercia."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Insulin, medicines, and other diabetes treatments.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"}],"imagenes":[{"ubicacion":"Sección de titulación","descripcion":"Tabla de ajuste de insulina basal según glucosa de ayuno y un registro de glucometrías.","alt":"Titulación de insulina basal en diabetes tipo 2"}],"keywords":["insulina basal diabetes tipo 2","titulación insulina basal","inicio insulina glargina","insulina basal glp-1","hipoglucemia insulina","dosis insulina basal","curso insulinoterapia diabetes"],"mapa":{"centro":"Insulina basal","ramas":[{"titulo":"Inicio","icono":"Syringe","nodos":["10 UI o 0,1-0,2 U/kg","Una vez al día","Educación"]},{"titulo":"Titulación","icono":"Target","nodos":["Glucosa de ayuno","Aumentos de 2 UI","Cada 3 días"]},{"titulo":"Combinación","icono":"Layers","nodos":["GLP-1","Metformina","Otros orales"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Hipoglucemia","Técnica","Conservación"]}]},"proceso":{"titulo":"Cómo iniciar y titular insulina basal","intro":"","pasos":[{"titulo":"Confirmar indicación","detalle":"HbA1c, síntomas, hiperglucemia grave o fracaso de otros fármacos.","icono":"Target","evidencia":"Indicación."},{"titulo":"Elegir la basal","detalle":"Glargina, detemir, degludec o NPH según cobertura y perfil.","icono":"Syringe","evidencia":"Selección."},{"titulo":"Iniciar","detalle":"10 UI o 0,1-0,2 U/kg al día.","icono":"Pill","evidencia":"Dosis inicial."},{"titulo":"Titular","detalle":"Ajustar cada 3 días según glucosa de ayuno.","icono":"RefreshCw","evidencia":"Registro."},{"titulo":"Seguir","detalle":"HbA1c, hipoglucemias, técnica y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Diez unidades durante seis meses","contexto":"Hombre de 60 años, diabetes tipo 2, HbA1c 9,1 %, insulina glargina 10 UI desde hace seis meses, glucosa de ayuno entre 180 y 220 mg/dL. No ha tenido hipoglucemias.","pregunta":"¿Cuál es la intervención más razonable?","opciones":[{"texto":"Mantener la dosis porque no tiene hipoglucemias.","correcta":false,"retro":"La dosis no está titulada y la glucosa sigue alta. La falta de hipoglucemia no significa que el tratamiento sea suficiente."},{"texto":"Proponer una titulación gradual con glucosa de ayuno y seguimiento.","correcta":true,"retro":"La insulina basal requiere titulación. Se ajusta cada 3 días y se educa sobre hipoglucemia."},{"texto":"Suspender la insulina y volver a los orales.","correcta":false,"retro":"La HbA1c alta y la glucosa de ayuno sugieren que necesita insulina. Suspenderla puede empeorar el control."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Inicio y titulación de insulina basal en DM2 y combinación con agonistas GLP-1$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Inicio y titulación de insulina basal en DM2 y combinación con agonistas GLP-1$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 03. Diabetes tipo 1: esquema basal-bolo, conteo de carbohidratos, bombas y sistemas automatizados
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La cuenta que cambia la glucosa","texto":"Una joven con diabetes tipo 1 quiere comer una arepa y no sabe cuánta insulina aplicar. Su esquema basal-bolo funciona, pero el conteo de carbohidratos es empírico. Con educación, una razón insulina-carbohidrato y monitoreo continuo, puede comer con más libertad y menos variabilidad. La diabetes tipo 1 no se maneja con una dosis fija: se maneja con un sistema."},"objetivos":["Explicar el esquema basal-bolo y sus componentes.","Aplicar el conteo de carbohidratos y la razón insulina-carbohidrato.","Reconocer el papel de las bombas y los sistemas automatizados.","Identificar los riesgos y la educación necesaria en diabetes tipo 1."],"conceptos":[{"icono":"Syringe","termino":"Basal-bolo","definicion":"Esquema con insulina basal para el fondo y bolos de insulina rápida para comidas y correcciones."},{"icono":"Wheat","termino":"Conteo de carbohidratos","definicion":"Estimación de los gramos de carbohidratos de cada comida para calcular el bolo."},{"icono":"Calculator","termino":"Razón insulina-carbohidrato","definicion":"Unidades de insulina rápida por cada gramo de carbohidrato, individualizada."},{"icono":"Cpu","termino":"Sistema automatizado","definicion":"Bomba de insulina con sensor que ajusta la basal según la glucosa; requiere supervisión y educación."}],"secciones":[{"titulo":"El esquema basal-bolo","parrafos":["La diabetes tipo 1 requiere insulina desde el diagnóstico. El esquema basal-bolo intenta imitar la fisiología: una basal para cubrir las necesidades entre comidas y durante la noche, y bolos de insulina rápida antes de cada comida. También se usa un bolo de corrección cuando la glucosa está alta.","La basal puede ser una insulina de acción prolongada o una bomba con infusión continua. Los bolos se calculan con la razón insulina-carbohidrato y el factor de corrección. La educación y el monitoreo son esenciales para ajustar."]},{"titulo":"Conteo de carbohidratos","parrafos":["El conteo estima los gramos de carbohidratos de la comida y los multiplica por la razón insulina-carbohidrato. Por ejemplo, si la razón es 1 unidad por 10 g y la comida tiene 50 g, el bolo es 5 unidades. La razón se individualiza y se ajusta con la respuesta.","No todos los carbohidratos elevan la glucosa igual. La fibra, la grasa, la proteína y el índice glucémico modifican la respuesta. El paciente aprende a observar, medir y ajustar. La educación continua y el registro son parte del tratamiento."]},{"titulo":"Bombas y sistemas automatizados","parrafos":["Las bombas de insulina administran basal continua y bolos. Los sistemas automatizados combinan un sensor de glucosa y un algoritmo que ajusta la basal y, en algunos casos, los bolos. Pueden mejorar el tiempo en rango y la calidad de vida, pero requieren educación, adherencia y revisión de datos.","Los riesgos incluyen cetoacidosis por falla de la bomba, infecciones en el sitio de infusión e hipoglucemia. El paciente debe saber qué hacer si la bomba falla y tener un plan de respaldo con insulina inyectada. El QF puede revisar la técnica, los insumos y la conservación."]}],"errores":[{"error":"Usar una dosis fija sin contar carbohidratos.","correccion":"El conteo y la razón individualizada mejoran el control."},{"error":"No tener plan de respaldo si falla la bomba.","correccion":"Se educa y se prescribe insulina inyectada de respaldo."},{"error":"Ajustar solo con una glucometría.","correccion":"Se revisan patrones y el tiempo en rango."}],"comprueba":[{"pregunta":"¿Qué compone el esquema basal-bolo?","respuesta":"Insulina basal para el fondo y bolos para comidas y correcciones."},{"pregunta":"¿Qué es la razón insulina-carbohidrato?","respuesta":"Unidades de insulina rápida por gramo de carbohidrato."},{"pregunta":"¿Qué riesgo tiene una bomba?","respuesta":"Cetoacidosis por falla, infección del sitio e hipoglucemia."}],"resumen":["La diabetes tipo 1 requiere **insulina desde el inicio**.","El esquema basal-bolo imita la fisiología.","El **conteo de carbohidratos** mejora la flexibilidad.","Bombas y sistemas automatizados requieren educación y respaldo."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Insulin, medicines, and other diabetes treatments.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"}],"imagenes":[{"ubicacion":"Sección de conteo","descripcion":"Plato con arepa, queso y fruta, con gramos de carbohidratos y cálculo del bolo.","alt":"Conteo de carbohidratos en diabetes tipo 1"}],"keywords":["diabetes tipo 1 basal bolo","conteo de carbohidratos","razón insulina carbohidrato","bomba de insulina","sistema automatizado diabetes","curso diabetes tipo 1"],"mapa":{"centro":"Diabetes tipo 1","ramas":[{"titulo":"Basal","icono":"Syringe","nodos":["Glargina o degludec","Bomba","Cubre el fondo"]},{"titulo":"Bolo","icono":"Pill","nodos":["Comida","Corrección","Rápida"]},{"titulo":"Conteo","icono":"Wheat","nodos":["Carbohidratos","Razón","Factor de corrección"]},{"titulo":"Tecnología","icono":"Cpu","nodos":["Sensor","Bomba","Automatización"]}]},"proceso":{"titulo":"Cómo apoyar un esquema basal-bolo","intro":"","pasos":[{"titulo":"Revisar el esquema","detalle":"Basal, bolos, correcciones y horarios.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Revisar datos","detalle":"Glucometrías, sensor, comida y actividad.","icono":"LineChart","evidencia":"Reporte."},{"titulo":"Ajustar","detalle":"Razón, factor de corrección y basal con el equipo.","icono":"Calculator","evidencia":"Ajuste."},{"titulo":"Educar","detalle":"Conteo, técnica, fallas de bomba e hipoglucemia.","icono":"GraduationCap","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Tiempo en rango, hipoglucemias y calidad de vida.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"La arepa sin contar","contexto":"Joven con diabetes tipo 1, esquema basal-bolo, razón 1 U por 10 g. Come una arepa con queso y no aplica bolo. Glucosa 280 mg/dL dos horas después.","pregunta":"¿Qué educación priorizar?","opciones":[{"texto":"Aumentar la basal.","correcta":false,"retro":"El problema es el bolo de la comida, no la basal."},{"texto":"Enseñar conteo de carbohidratos y calcular el bolo correspondiente.","correcta":true,"retro":"La comida sin bolo eleva la glucosa posprandial. El conteo permite ajustar."},{"texto":"Prohibir la arepa.","correcta":false,"retro":"La educación permite incluir alimentos con control, no prohibirlos de forma rígida."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Diabetes tipo 1: esquema basal-bolo, conteo de carbohidratos, bombas y sistemas automatizados$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Diabetes tipo 1: esquema basal-bolo, conteo de carbohidratos, bombas y sistemas automatizados$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. Técnica de inyección con pluma, rotación de sitios, lipohipertrofia y conservación
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La lipohipertrofia que cambió la absorción","texto":"Un paciente inyecta insulina siempre en el mismo punto del abdomen. La zona se vuelve dura y la glucosa empieza a subir y bajar sin explicación. La lipohipertrofia altera la absorción y es una causa frecuente de variabilidad. La técnica de inyección no es un detalle: es parte de la dosis."},"objetivos":["Aplicar la técnica correcta de inyección con pluma.","Explicar la rotación de sitios y prevenir la lipohipertrofia.","Reconocer las reglas de conservación de la insulina.","Identificar errores de técnica y su impacto en la glucosa."],"conceptos":[{"icono":"Syringe","termino":"Pluma","definicion":"Dispositivo precargado que administra insulina subcutánea; requiere aguja, cebado y técnica."},{"icono":"RefreshCw","termino":"Rotación","definicion":"Cambio de sitio de inyección para evitar lipohipertrofia y mejorar la absorción."},{"icono":"AlertTriangle","termino":"Lipohipertrofia","definicion":"Acumulación de grasa en el sitio de inyección; altera la absorción y la glucosa."},{"icono":"Snowflake","termino":"Conservación","definicion":"Reglas de temperatura y tiempo para mantener la insulina estable."}],"secciones":[{"titulo":"Técnica paso a paso","parrafos":["La técnica incluye lavarse las manos, revisar la insulina, colocar una aguja nueva, cebar la pluma si es necesario, seleccionar la dosis y aplicar en el sitio elegido. La aguja debe entrar en el tejido subcutáneo, generalmente a 90 grados, y la insulina se inyecta lentamente. No se debe masajear el sitio.","La aguja se retira y se desecha en un contenedor de objetos cortopunzantes. No se reutiliza. La reutilización aumenta el riesgo de infección, lipohipertrofia y dolor. El QF puede observar la técnica y corregir errores."]},{"titulo":"Rotación y lipohipertrofia","parrafos":["La rotación de sitios dentro de una misma zona y entre zonas ayuda a prevenir la lipohipertrofia. Se recomienda cambiar el punto de inyección al menos cada vez, con un patrón ordenado. La lipohipertrofia se reconoce por una zona indurada o abultada; si existe, se evita hasta que se recupere.","La absorción en una zona con lipohipertrofia es errática. El paciente puede tener hiperglucemia y luego hipoglucemia sin cambiar la dosis. La educación y la revisión de los sitios son parte del control."]},{"titulo":"Conservación","parrafos":["La insulina sin abrir se conserva refrigerada, sin congelar, hasta la fecha de vencimiento. Una vez abierta, se puede mantener a temperatura ambiente durante el tiempo indicado por el fabricante, evitando el calor y la luz directa. No se debe usar si está turbia, con partículas o cambios de color, salvo las insulinas que son turbias por diseño.","El QF puede revisar la cadena de frío, el transporte y el almacenamiento en el hogar. Una insulina mal conservada pierde potencia y puede explicar un control inexplicablemente malo."]}],"errores":[{"error":"Reutilizar agujas.","correccion":"Aumenta el dolor, la infección y la lipohipertrofia."},{"error":"Inyectar siempre en el mismo punto.","correccion":"Rotar para mantener una absorción estable."},{"error":"Guardar la pluma cerca del calor.","correccion":"La insulina pierde potencia; revisar conservación."}],"comprueba":[{"pregunta":"¿Cómo se previene la lipohipertrofia?","respuesta":"Rotando los sitios de inyección y usando agujas nuevas."},{"pregunta":"¿Dónde se inyecta la insulina?","respuesta":"En tejido subcutáneo: abdomen, muslo o brazo, según la técnica."},{"pregunta":"¿Cómo se conserva la insulina sin abrir?","respuesta":"Refrigerada, sin congelar, hasta la fecha de vencimiento."}],"resumen":["La **técnica** influye en la absorción y en la glucosa.","La **rotación** previene lipohipertrofia.","La aguja no se reutiliza.","La **conservación** mantiene la potencia."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Insulin, medicines, and other diabetes treatments.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"}],"imagenes":[{"ubicacion":"Sección de técnica","descripcion":"Ilustración de los sitios de inyección y un patrón de rotación, con una zona de lipohipertrofia marcada.","alt":"Sitios de inyección y rotación de insulina"}],"keywords":["técnica de inyección de insulina","rotación de sitios insulina","lipohipertrofia insulina","conservación de insulina","pluma de insulina","aguja insulina","curso insulinoterapia"],"mapa":{"centro":"Técnica de inyección","ramas":[{"titulo":"Antes","icono":"Hand","nodos":["Lavado de manos","Aguja nueva","Cebado"]},{"titulo":"Inyección","icono":"Syringe","nodos":["90 grados","Subcutánea","No masajear"]},{"titulo":"Sitios","icono":"MapPin","nodos":["Abdomen","Muslo","Brazo","Rotación"]},{"titulo":"Después","icono":"Snowflake","nodos":["No reutilizar aguja","Conservación","Desecho"]}]},"proceso":{"titulo":"Revisión de la técnica de inyección","intro":"","pasos":[{"titulo":"Observar","detalle":"Pedir al paciente que demuestre la técnica con una pluma de práctica.","icono":"Eye","evidencia":"Observación."},{"titulo":"Revisar insumos","detalle":"Agujas, pluma, conservación y desecho.","icono":"Package","evidencia":"Insumos."},{"titulo":"Revisar sitios","detalle":"Buscar lipohipertrofia y patrón de rotación.","icono":"MapPin","evidencia":"Examen."},{"titulo":"Corregir","detalle":"Enseñar y practicar la técnica correcta.","icono":"GraduationCap","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Revisar glucosa y técnica en cada control.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Siempre en el mismo punto","contexto":"Paciente con insulina basal y glucosa variable. En el abdomen hay una zona indurada de 3 cm donde siempre inyecta.","pregunta":"¿Qué explicación es más probable?","opciones":[{"texto":"La insulina está vencida.","correcta":false,"retro":"Puede ser, pero la lipohipertrofia es una causa directa de absorción errática."},{"texto":"La lipohipertrofia altera la absorción; debe rotar sitios y evitar la zona.","correcta":true,"retro":"La zona indurada cambia la absorción y explica la variabilidad."},{"texto":"Necesita una dosis más alta sin cambiar la técnica.","correcta":false,"retro":"Aumentar la dosis sin corregir la técnica puede causar hipoglucemia."}]}}$j$::jsonb;
