  -- 05. Monitoreo continuo de glucosa y glucometría: interpretación del reporte AGP
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El promedio que esconde las noches","texto":"Un paciente tiene HbA1c de 7,2 % y cree que todo está bien. El reporte AGP muestra hipoglucemias nocturnas tres veces por semana y hiperglucemias después del desayuno. El promedio oculta el patrón. El monitoreo continuo permite ver lo que la HbA1c no muestra y ajustar con precisión."},"objetivos":["Interpretar el tiempo en rango y el reporte AGP.","Diferenciar glucometría capilar y monitoreo continuo.","Identificar patrones de hipoglucemia e hiperglucemia.","Usar los datos para educar y ajustar el tratamiento."],"conceptos":[{"icono":"LineChart","termino":"AGP","definicion":"Reporte ambulatorio de glucosa que resume patrones por hora y días, con tiempo en rango y variabilidad."},{"icono":"Timer","termino":"Tiempo en rango","definicion":"Porcentaje de tiempo con glucosa entre 70 y 180 mg/dL."},{"icono":"Activity","termino":"Variabilidad","definicion":"Fluctuación de la glucosa; una alta variabilidad se asocia con más hipoglucemias."},{"icono":"AlertTriangle","termino":"Hipoglucemia nocturna","definicion":"Glucosa baja durante la noche; puede pasar desapercibida y causar sudoración, pesadillas o cefalea."}],"secciones":[{"titulo":"Qué muestra el AGP","parrafos":["El reporte AGP resume la glucosa de varios días. Muestra el tiempo en rango, el tiempo por encima y por debajo, la glucosa promedio, la variabilidad y los patrones por hora del día. Es una herramienta visual que ayuda a identificar cuándo ocurren los problemas, no solo si ocurren.","La glucometría capilar mide puntos aislados; el monitoreo continuo mide de forma intermitente el líquido intersticial. El sensor tiene un retraso de unos minutos respecto a la glucosa capilar y puede ser menos preciso en cambios rápidos o en ciertas situaciones. Se usa para tendencias y patrones, no para decisiones aisladas."]},{"titulo":"Cómo leerlo","parrafos":["Primero se revisa el tiempo en rango y el tiempo por debajo de 70 mg/dL. Si hay hipoglucemias, se busca el horario y la causa: insulina, comida, ejercicio o alcohol. Luego se revisan las hiperglucemias posprandiales y las de ayuno. Las líneas del AGP muestran si el patrón se repite.","No se ajusta todo a la vez. Se elige un patrón prioritario, se hace un cambio y se evalúa. La educación incluye cómo escanear el sensor, calibrar si es necesario, interpretar las flechas de tendencia y actuar ante una hipoglucemia."]},{"titulo":"Uso en la consulta farmacéutica","parrafos":["El QF puede revisar el reporte con el paciente, identificar errores de técnica, horarios de insulina y alimentos que elevan la glucosa. También puede detectar hipoglucemias nocturnas y reforzar la educación. La revisión conjunta mejora la comprensión y la adherencia.","El reporte no reemplaza la HbA1c ni la evaluación clínica. Se integra con síntomas, medicamentos, actividad y alimentación. La meta es un patrón seguro y estable, no solo un número."]}],"errores":[{"error":"Ajustar solo con la HbA1c.","correccion":"El AGP muestra patrones y hipoglucemias que el promedio oculta."},{"error":"Tomar decisiones con una sola lectura.","correccion":"Se usan tendencias y patrones de varios días."},{"error":"No revisar la técnica del sensor.","correccion":"La calibración, la colocación y el retraso afectan la interpretación."}],"comprueba":[{"pregunta":"¿Qué es el tiempo en rango?","respuesta":"El porcentaje de tiempo con glucosa entre 70 y 180 mg/dL."},{"pregunta":"¿Qué muestra el AGP?","respuesta":"Patrones por hora, tiempo en rango, variabilidad e hipoglucemias."},{"pregunta":"¿Qué se revisa primero?","respuesta":"Las hipoglucemias y el tiempo por debajo de 70 mg/dL."}],"resumen":["El AGP muestra **patrones**, no solo promedios.","La **hipoglucemia** es prioritaria.","Se cambia un patrón a la vez.","El sensor complementa la glucometría y la HbA1c."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Continuous glucose monitoring.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/managing-diabetes/continuous-glucose-monitoring"}],"imagenes":[{"ubicacion":"Sección del AGP","descripcion":"Reporte AGP simplificado con bandas de tiempo en rango y una hipoglucemia nocturna marcada.","alt":"Interpretación del reporte AGP de glucosa"}],"keywords":["reporte agp","monitoreo continuo de glucosa","tiempo en rango","glucometría","hipoglucemia nocturna","sensor de glucosa","curso diabetes monitoreo"],"mapa":{"centro":"Reporte AGP","ramas":[{"titulo":"Tiempo en rango","icono":"Timer","nodos":["70-180 mg/dL","Meta >70 %","Menos de 4 % bajo 70"]},{"titulo":"Patrones","icono":"LineChart","nodos":["Ayunas","Posprandial","Nocturno"]},{"titulo":"Variabilidad","icono":"Activity","nodos":["Subidas","Caídas","Estabilidad"]},{"titulo":"Acción","icono":"Target","nodos":["Ajustar insulina","Comida","Actividad"]}]},"proceso":{"titulo":"Cómo interpretar un AGP en cinco pasos","intro":"","pasos":[{"titulo":"Revisar el tiempo en rango","detalle":"Porcentaje entre 70 y 180 mg/dL y tiempo bajo 70.","icono":"Timer","evidencia":"Reporte."},{"titulo":"Buscar hipoglucemias","detalle":"Horario, frecuencia, síntomas y causas.","icono":"AlertTriangle","evidencia":"Patrón."},{"titulo":"Revisar hiperglucemias","detalle":"Ayuno, posprandial y nocturno.","icono":"LineChart","evidencia":"Patrón."},{"titulo":"Elegir un cambio","detalle":"Ajustar insulina, comida o actividad.","icono":"Target","evidencia":"Plan."},{"titulo":"Evaluar","detalle":"Revisar el efecto en el siguiente reporte.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Hipoglucemias a las 3 a. m.","contexto":"Paciente con insulina basal, HbA1c 7,2 %, AGP con glucosa <70 mg/dL a las 3 a. m. tres veces por semana y glucosa de ayuno 160 mg/dL.","pregunta":"¿Qué patrón es prioritario?","opciones":[{"texto":"Aumentar la basal por la glucosa de ayuno alta.","correcta":false,"retro":"Aumentar la basal puede empeorar las hipoglucemias nocturnas. Primero se investiga el patrón."},{"texto":"Revisar la hipoglucemia nocturna antes de ajustar la basal.","correcta":true,"retro":"La hipoglucemia nocturna es un evento de seguridad. Se revisa la dosis, la comida y la actividad."},{"texto":"Ignorar el AGP porque la HbA1c es buena.","correcta":false,"retro":"La HbA1c no muestra las hipoglucemias. El AGP es clave."}]}}$j$::jsonb;
