  -- 06. Hipoglucemia: clasificación, regla de los 15, glucagón y prevención
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La regla que salva una vida","texto":"Un paciente con insulina siente sudoración y temblor. Su glucosa es 55 mg/dL. En lugar de comer un dulce y esperar, aplica la regla de los 15: 15 g de carbohidrato rápido, espera 15 minutos y vuelve a medir. Si no sube, repite. La educación simple evita convulsiones y hospitalizaciones."},"objetivos":["Clasificar la hipoglucemia por glucosa y gravedad.","Aplicar la regla de los 15 y el tratamiento de la hipoglucemia grave.","Reconocer el papel del glucagón y cuándo usarlo.","Diseñar un plan de prevención y educación."],"conceptos":[{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Glucosa <70 mg/dL. Se clasifica en leve, clínicamente significativa o grave según síntomas y necesidad de ayuda."},{"icono":"Timer","termino":"Regla de los 15","definicion":"15 g de carbohidrato rápido, esperar 15 minutos y volver a medir; repetir si sigue baja."},{"icono":"Syringe","termino":"Glucagón","definicion":"Hormona que eleva la glucosa en hipoglucemia grave cuando el paciente no puede comer."},{"icono":"ShieldCheck","termino":"Prevención","definicion":"Ajuste de insulina, educación, horarios de comida y revisión de patrones."}],"secciones":[{"titulo":"Clasificación","parrafos":["La hipoglucemia se define por glucosa <70 mg/dL. La leve se trata con carbohidrato rápido y el paciente puede hacerlo solo. La clínicamente significativa requiere ayuda o causa deterioro. La grave se asocia con alteración del estado de conciencia, convulsiones o necesidad de glucagón o atención urgente.","Los síntomas incluyen sudoración, temblor, palpitaciones, ansiedad, hambre, mareo y confusión. Algunos pacientes no tienen síntomas (hipoglucemia inadvertida), sobre todo con diabetes de larga evolución o uso de betabloqueadores."]},{"titulo":"Regla de los 15","parrafos":["Si el paciente está consciente y puede tragar, se administran 15 g de carbohidrato rápido: 3 a 4 tabletas de glucosa, 120 a 150 ml de jugo o refresco regular, o una cucharada de azúcar. Se espera 15 minutos y se mide de nuevo. Si sigue <70 mg/dL, se repite. Cuando la glucosa sube, se ofrece una comida o snack con carbohidrato complejo.","No se debe usar chocolate solo, porque la grasa enlentece la absorción. No se debe administrar insulina ni sulfonilurea durante la hipoglucemia. Si el paciente está inconsciente o no puede tragar, no se le da comida ni líquido por boca: se usa glucagón y se busca atención urgente."]},{"titulo":"Glucagón y prevención","parrafos":["El glucagón está indicado en hipoglucemia grave cuando el paciente no puede comer. Puede administrarse por vía intramuscular, subcutánea o intranasal, según la presentación. El paciente y el cuidador deben saber dónde está, cómo se usa y cuándo llamar a urgencias. Después de recuperar la conciencia, se administra carbohidrato oral.","La prevención incluye revisar la dosis de insulina, los horarios de comida, el ejercicio, el alcohol y los patrones del AGP. La educación debe repetirse y adaptarse al nivel de alfabetización. El QF puede revisar el plan y asegurar que el paciente tenga glucagón disponible."]}],"errores":[{"error":"Dar comida a un paciente inconsciente.","correccion":"Riesgo de aspiración; se usa glucagón y urgencias."},{"error":"No volver a medir la glucosa.","correccion":"Hay que confirmar que subió y repetir si es necesario."},{"error":"No revisar la causa.","correccion":"La hipoglucemia recurrente exige ajustar el tratamiento y educar."}],"comprueba":[{"pregunta":"¿Qué es la regla de los 15?","respuesta":"15 g de carbohidrato rápido, esperar 15 minutos y medir de nuevo."},{"pregunta":"¿Cuándo se usa glucagón?","respuesta":"En hipoglucemia grave con incapacidad para tragar o alteración de la conciencia."},{"pregunta":"¿Qué no se debe dar en hipoglucemia grave?","respuesta":"Comida o líquido por boca si el paciente no puede tragar."}],"resumen":["La hipoglucemia se define por **glucosa <70 mg/dL**.","La regla de los 15 es el tratamiento inicial.","El glucagón es para la hipoglucemia grave.","La prevención exige revisar dosis, comida y patrones."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Low blood glucose (hypoglycemia).","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/low-blood-glucose-hypoglycemia"}],"imagenes":[{"ubicacion":"Sección de regla de los 15","descripcion":"Infografía con 15 g de glucosa, reloj de 15 minutos y medidor, y una lista de opciones rápidas.","alt":"Regla de los 15 para tratar la hipoglucemia"}],"keywords":["hipoglucemia regla de los 15","hipoglucemia grave glucagón","síntomas de hipoglucemia","tratamiento hipoglucemia","prevención hipoglucemia","diabetes insulina hipoglucemia","curso diabetes"],"mapa":{"centro":"Hipoglucemia","ramas":[{"titulo":"Leve","icono":"AlertTriangle","nodos":["70 mg/dL","Síntomas","Autotratamiento"]},{"titulo":"Grave","icono":"Syringe","nodos":["Ayuda de terceros","Glucagón","Urgencia"]},{"titulo":"Tratamiento","icono":"Timer","nodos":["15 g","15 minutos","Repetir"]},{"titulo":"Prevención","icono":"ShieldCheck","nodos":["Ajustar insulina","Comidas","Educación"]}]},"proceso":{"titulo":"Actuación ante una hipoglucemia","intro":"","pasos":[{"titulo":"Reconocer","detalle":"Síntomas y medición si es posible.","icono":"AlertTriangle","evidencia":"Glucosa."},{"titulo":"Evaluar conciencia","detalle":"Si puede tragar, carbohidrato oral; si no, glucagón.","icono":"Users","evidencia":"Evaluación."},{"titulo":"Regla de los 15","detalle":"15 g, 15 minutos, repetir si es necesario.","icono":"Timer","evidencia":"Registro."},{"titulo":"Estabilizar","detalle":"Comida con carbohidrato complejo y revisar causa.","icono":"Wheat","evidencia":"Plan."},{"titulo":"Prevenir","detalle":"Ajustar tratamiento y educar.","icono":"ShieldCheck","evidencia":"Seguimiento."}]},"caso":{"titulo":"Glucosa 52 y consciente","contexto":"Paciente con insulina, sudoración y temblor, glucosa 52 mg/dL. Está consciente y puede tragar.","pregunta":"¿Qué hacer primero?","opciones":[{"texto":"Aplicar insulina rápida para estabilizar.","correcta":false,"retro":"La insulina baja más la glucosa. Es peligroso."},{"texto":"Dar 15 g de carbohidrato rápido, esperar 15 minutos y volver a medir.","correcta":true,"retro":"La regla de los 15 es el tratamiento inicial de la hipoglucemia leve en paciente consciente."},{"texto":"Dar chocolate y esperar una hora.","correcta":false,"retro":"La grasa del chocolate enlentece la absorción; no es la mejor opción para corregir rápido."}]}}$j$::jsonb;
