  -- 07. Caso: inicio de insulina basal en una persona con DM2 e hiperglucemia grave
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La glucosa de 410 y el paciente que se siente bien","texto":"Un hombre de 52 años llega con glucosa de 410 mg/dL, HbA1c de 12,4 %, pérdida de peso y sed intensa. Se siente cansado, pero no tiene cetonas. El médico indica insulina basal. El paciente tiene miedo a las agujas y no sabe medir su glucosa. La educación y la titulación son tan importantes como la dosis inicial."},"objetivos":["Reconocer los criterios de inicio de insulina en hiperglucemia grave.","Diseñar un esquema inicial seguro y un plan de titulación.","Educar sobre técnica, hipoglucemia y automonitoreo.","Coordinar el seguimiento y la transición a un esquema ambulatorio."],"conceptos":[{"icono":"Syringe","termino":"Insulina basal","definicion":"Insulina de acción prolongada para controlar la glucosa de ayuno y entre comidas."},{"icono":"Target","termino":"Hiperglucemia grave","definicion":"Glucosa muy elevada con síntomas catabólicos; puede requerir insulina desde el inicio."},{"icono":"Users","termino":"Educación","definicion":"Enseñanza de técnica, medición, hipoglucemia y adherencia antes del alta."},{"icono":"CalendarClock","termino":"Seguimiento","definicion":"Revisión cercana de glucosa, tolerancia y ajuste de dosis."}],"secciones":[{"titulo":"Cuándo la insulina es prioritaria","parrafos":["La insulina se inicia cuando hay hiperglucemia grave, síntomas de catabolismo, pérdida de peso, cetonas o cuando no se alcanza la meta con otros fármacos. En este caso, la glucosa de 410 mg/dL y la HbA1c de 12,4 % indican un control muy deficiente y riesgo de complicaciones.","La insulina basal puede iniciarse en el ambulatorio si el paciente está estable y tiene educación. Si hay cetonas, deshidratación o alteración del estado general, se requiere evaluación urgente. La decisión depende de la seguridad y del soporte disponible."]},{"titulo":"Esquema y educación","parrafos":["Se puede iniciar con 10 UI al día o 0,2 UI/kg, con titulación cada tres días según la glucosa de ayuno. La educación incluye técnica de inyección, conservación, medición de glucosa, reconocimiento de hipoglucemia y qué hacer si olvida una dosis. El paciente debe tener un plan escrito.","El miedo a las agujas es común. Se puede explorar, mostrar la pluma, practicar con un dispositivo de entrenamiento y elegir el sitio menos doloroso. La educación debe ser paciente y repetitiva. El QF puede acompañar la primera aplicación."]},{"titulo":"Seguimiento y ajuste","parrafos":["El seguimiento debe ser cercano: glucometrías, síntomas, hipoglucemias y adherencia. La dosis se ajusta con la glucosa de ayuno. Si la glucosa posprandial sigue alta, se puede añadir un GLP-1 o insulina prandial, según el caso. La transición debe ser coordinada con el equipo tratante.","La meta inicial no es la perfección, sino la seguridad y la reducción gradual de la glucosa. Una bajada demasiado rápida puede causar hipoglucemia o edema. La educación y el seguimiento evitan complicaciones."]}],"errores":[{"error":"Iniciar insulina sin educación.","correccion":"La técnica, la hipoglucemia y la medición deben enseñarse antes."},{"error":"No titular la dosis.","correccion":"La insulina basal requiere ajuste según la glucosa de ayuno."},{"error":"Bajar la glucosa demasiado rápido.","correccion":"La reducción debe ser gradual y segura."}],"comprueba":[{"pregunta":"¿Cuándo se inicia insulina en DM2?","respuesta":"En hiperglucemia grave, síntomas catabólicos o fracaso de otros fármacos."},{"pregunta":"¿Qué educación es obligatoria?","respuesta":"Técnica, conservación, medición, hipoglucemia y qué hacer si olvida una dosis."},{"pregunta":"¿Cómo se titula?","respuesta":"Con la glucosa de ayuno, cada 3 días."}],"resumen":["La insulina se inicia en **hiperglucemia grave** con evaluación de seguridad.","La **educación** es parte del tratamiento.","La titulación se basa en la glucosa de ayuno.","El seguimiento cercano evita hipoglucemias y abandono."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"National Institute of Diabetes and Digestive and Kidney Diseases. Insulin, medicines, and other diabetes treatments.","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/insulin-medicines-treatments"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente con glucómetro, pluma de insulina y un plan escrito de titulación y hipoglucemia.","alt":"Inicio de insulina basal en hiperglucemia grave"}],"keywords":["inicio de insulina basal","hiperglucemia grave diabetes","insulina en diabetes tipo 2","educación insulina","titulación insulina","caso clínico insulina","curso insulinoterapia"],"mapa":{"centro":"Inicio de insulina","ramas":[{"titulo":"Indicación","icono":"Target","nodos":["HbA1c alta","Síntomas","Pérdida de peso"]},{"titulo":"Esquema","icono":"Syringe","nodos":["Basal","10 UI o 0,2 U/kg","Titulación"]},{"titulo":"Educación","icono":"Users","nodos":["Técnica","Hipoglucemia","Medición"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Glucometrías","HbA1c","Adherencia"]}]},"proceso":{"titulo":"Inicio de insulina en hiperglucemia grave","intro":"","pasos":[{"titulo":"Evaluar gravedad","detalle":"Cetonas, deshidratación, síntomas y comorbilidad.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Iniciar basal","detalle":"10 UI o 0,2 U/kg al día.","icono":"Syringe","evidencia":"Dosis."},{"titulo":"Educar","detalle":"Técnica, medición, hipoglucemia y conservación.","icono":"Users","evidencia":"Educación."},{"titulo":"Titular","detalle":"Ajustar cada 3 días con glucosa de ayuno.","icono":"RefreshCw","evidencia":"Registro."},{"titulo":"Seguir","detalle":"HbA1c, hipoglucemias y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Miedo a la aguja","contexto":"Paciente con glucosa 410 mg/dL, HbA1c 12,4 %, sin cetonas, con miedo a las agujas y sin medidor de glucosa.","pregunta":"¿Qué hacer antes del alta?","opciones":[{"texto":"Solo prescribir insulina y explicar la dosis.","correcta":false,"retro":"Sin educación, técnica y medición, el riesgo de hipoglucemia y abandono es alto."},{"texto":"Enseñar técnica, entregar medidor, explicar hipoglucemia y programar seguimiento cercano.","correcta":true,"retro":"La educación y el seguimiento son parte del tratamiento inicial."},{"texto":"Esperar a que el paciente compre el medidor por su cuenta.","correcta":false,"retro":"La falta de acceso al medidor impide la titulación segura."}]}}$j$::jsonb;
