  -- 08. Introducción a la unidad: la persona con diabetes y múltiples comorbilidades
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No es solo diabetes","texto":"Un paciente de 68 años tiene diabetes, insuficiencia cardíaca, enfermedad renal, obesidad y artrosis. Toma ocho medicamentos y ha tenido dos hospitalizaciones. La diabetes no se trata en una columna aparte: interactúa con el corazón, el riñón, el peso, la fragilidad y el acceso. La unidad 5 integra todo eso."},"objetivos":["Reconocer la diabetes como parte de un síndrome cardiometabólico.","Priorizar problemas en pacientes con múltiples comorbilidades.","Evitar la polifarmacia innecesaria y las interacciones.","Diseñar un plan centrado en la persona y no solo en la glucosa."],"conceptos":[{"icono":"Activity","termino":"Cardiometabólico","definicion":"Conjunto de factores que incluyen glucosa, presión, lípidos, peso, riñón y corazón."},{"icono":"Layers","termino":"Polifarmacia","definicion":"Uso de múltiples medicamentos; aumenta el riesgo de interacciones y efectos adversos."},{"icono":"Target","termino":"Prioridad","definicion":"Problema que más afecta la seguridad o la calidad de vida en un momento dado."},{"icono":"Users","termino":"Persona","definicion":"Preferencias, creencias, acceso y red de apoyo; parte central del plan."}],"secciones":[{"titulo":"La diabetes no va sola","parrafos":["La diabetes tipo 2 se asocia con hipertensión, dislipidemia, obesidad, enfermedad cardiovascular, insuficiencia cardíaca y enfermedad renal. Estas condiciones comparten mecanismos y tratamientos. Un fármaco puede mejorar la glucosa y, al mismo tiempo, reducir eventos cardiorrenales o aumentar el riesgo.","El enfoque debe ser integral. No se trata de sumar fármacos para cada cifra, sino de elegir los que aportan beneficio y evitar los que suman riesgo. La revisión de la medicación completa es esencial."]},{"titulo":"Priorizar y simplificar","parrafos":["En un paciente con múltiples comorbilidades, no todo se puede optimizar al mismo tiempo. Se prioriza lo que más amenaza la seguridad: hipoglucemias, interacciones, insuficiencia cardíaca descompensada o progresión renal. Luego se abordan la glucosa, la presión y los lípidos.","La simplificación puede mejorar la adherencia. Un esquema con menos tomas, menos interacciones y menos costo puede ser más eficaz que uno teóricamente perfecto pero imposible de seguir. La decisión se comparte con el paciente."]},{"titulo":"El plan centrado en la persona","parrafos":["El plan incluye metas realistas, educación, acceso, apoyo familiar y seguimiento. La diabetes afecta la vida diaria: alimentación, trabajo, sueño, actividad y emociones. El QF puede explorar esas dimensiones y adaptar el tratamiento.","La unidad 5 aborda la enfermedad cardiovascular, la insuficiencia cardíaca, la enfermedad renal, la obesidad, el seguimiento farmacoterapéutico y la farmacovigilancia. El objetivo es integrar, no fragmentar."]}],"errores":[{"error":"Tratar cada cifra por separado.","correccion":"La diabetes y las comorbilidades comparten mecanismos y tratamientos."},{"error":"Añadir fármacos sin revisar interacciones.","correccion":"La polifarmacia aumenta el riesgo; revisar antes de añadir."},{"error":"Ignorar la fragilidad y el acceso.","correccion":"El plan debe ser realista y centrado en la persona."}],"comprueba":[{"pregunta":"¿Qué es el síndrome cardiometabólico?","respuesta":"La interacción entre glucosa, presión, lípidos, peso, riñón y corazón."},{"pregunta":"¿Qué se prioriza en un paciente complejo?","respuesta":"El riesgo más urgente: hipoglucemia, interacciones, insuficiencia cardíaca o progresión renal."},{"pregunta":"¿Por qué simplificar?","respuesta":"Para mejorar la adherencia y reducir interacciones y carga de medicamentos."}],"resumen":["La diabetes es parte de un **síndrome cardiometabólico**.","La prioridad es el riesgo que más amenaza al paciente.","La **revisión integral** evita polifarmacia innecesaria.","El plan debe ser realista y centrado en la persona."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"Organización Mundial de la Salud. Diabetes: datos y cifras.","url":"https://www.who.int/es/news-room/fact-sheets/detail/diabetes"}],"imagenes":[{"ubicacion":"Apertura de la unidad","descripcion":"Paciente en el centro con iconos de corazón, riñón, balanza y medicamentos alrededor.","alt":"Diabetes y múltiples comorbilidades"}],"keywords":["diabetes comorbilidades","síndrome cardiometabólico","polifarmacia diabetes","diabetes insuficiencia cardiaca erc","prioridades diabetes","curso farmacoterapia diabetes"],"mapa":{"centro":"Diabetes y comorbilidad","ramas":[{"titulo":"Corazón","icono":"Activity","nodos":["Insuficiencia cardíaca","Eventos","Presión"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG","Albuminuria","Nefroprotección"]},{"titulo":"Peso","icono":"Scale","nodos":["Obesidad","Sarcopenia","Metas"]},{"titulo":"Persona","icono":"Users","nodos":["Fragilidad","Acceso","Preferencias"]}]},"proceso":{"titulo":"Cómo abordar al paciente con comorbilidades","intro":"","pasos":[{"titulo":"Listar problemas","detalle":"Glucosa, corazón, riñón, peso, fragilidad y acceso.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Priorizar","detalle":"Identificar el riesgo más urgente.","icono":"Target","evidencia":"Prioridad."},{"titulo":"Revisar medicamentos","detalle":"Indicaciones, duplicidades e interacciones.","icono":"Search","evidencia":"Revisión."},{"titulo":"Simplificar","detalle":"Elegir un plan realista y seguro.","icono":"Layers","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Revisar respuesta y calidad de vida.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Ocho medicamentos y dos hospitalizaciones","contexto":"Paciente de 68 años con diabetes, insuficiencia cardíaca, ERC, obesidad y artrosis. Toma ocho medicamentos y ha tenido dos hospitalizaciones en seis meses.","pregunta":"¿Cuál es el primer paso?","opciones":[{"texto":"Añadir otro antidiabético para bajar la HbA1c.","correcta":false,"retro":"Antes de añadir, hay que revisar la medicación, las interacciones y la causa de las hospitalizaciones."},{"texto":"Revisar la medicación completa, priorizar riesgos y simplificar el esquema con el paciente.","correcta":true,"retro":"La revisión integral detecta duplicidades, interacciones y barreras antes de añadir más fármacos."},{"texto":"Suspender todo y empezar de cero.","correcta":false,"retro":"No se suspende sin evaluar; se revisa y se ajusta con criterio."}]}}$j$::jsonb;
