  -- 09. Diabetes, enfermedad cardiovascular e insuficiencia cardíaca: manejo farmacológico integral
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El mismo paciente, dos riesgos","texto":"Un paciente con diabetes y enfermedad coronaria recibe solo metformina. Otro con diabetes e insuficiencia cardíaca recibe un iSGLT2 y un GLP-1. Los dos tienen diabetes, pero el riesgo cardiovascular y el tratamiento no son iguales. La enfermedad cardiovascular y la insuficiencia cardíaca exigen fármacos con beneficio demostrado."},"objetivos":["Reconocer el riesgo cardiovascular y de insuficiencia cardíaca en diabetes.","Seleccionar fármacos con beneficio cardiovascular.","Integrar el tratamiento de la diabetes con el de la insuficiencia cardíaca.","Revisar interacciones y seguridad en la polifarmacia."],"conceptos":[{"icono":"Activity","termino":"Aterosclerosis","definicion":"Enfermedad de las arterias que causa infarto e ictus; los GLP-1 con evidencia reducen eventos."},{"icono":"Droplets","termino":"Insuficiencia cardíaca","definicion":"Síndrome de congestión o bajo gasto; los iSGLT2 reducen hospitalizaciones y muerte."},{"icono":"ShieldCheck","termino":"Beneficio demostrado","definicion":"Reducción de eventos en ensayos clínicos, no solo descenso de la HbA1c."},{"icono":"Layers","termino":"Terapia integral","definicion":"Combinación de medidas para glucosa, presión, lípidos, peso y corazón."}],"secciones":[{"titulo":"Enfermedad cardiovascular aterosclerótica","parrafos":["En pacientes con enfermedad coronaria, cerebrovascular o arterial periférica, los agonistas GLP-1 con evidencia reducen eventos cardiovasculares mayores. También se optimizan la presión, el LDL, el tabaco y el peso. La metformina puede formar parte del esquema, pero no sustituye el beneficio cardiovascular de otros fármacos.","La elección del GLP-1 depende de la evidencia específica, la cobertura y la tolerancia. La semaglutida y la liraglutida tienen estudios cardiovasculares; otros agonistas también. La decisión debe basarse en el perfil del paciente y en la ficha técnica."]},{"titulo":"Insuficiencia cardíaca","parrafos":["En insuficiencia cardíaca, los iSGLT2 reducen hospitalizaciones y muerte cardiovascular, independientemente de la diabetes. Se integran con diuréticos, betabloqueadores, IECA/ARA-II o sacubitrilo-valsartán y antagonistas de mineralocorticoides. La revisión del volumen y la función renal es esencial.","Los GLP-1 también se han estudiado en insuficiencia cardíaca, con resultados que dependen de la población y del fármaco. La prioridad es el iSGLT2, y el GLP-1 se considera según el riesgo cardiovascular, el peso y la evidencia."]},{"titulo":"Integrar y revisar","parrafos":["La polifarmacia es frecuente. Se revisan interacciones, duplicidades y efectos adversos. Los iSGLT2 pueden interactuar con diuréticos y aumentar el riesgo de deshidratación. Los GLP-1 pueden reducir el apetito y la ingesta. La insulina y las sulfonilureas aumentan el riesgo de hipoglucemia.","El QF puede revisar la medicación completa, la adherencia y los síntomas. La educación sobre hipoglucemia, volumen y días de enfermedad es parte del plan. La meta es reducir eventos y mejorar la calidad de vida."]}],"errores":[{"error":"Tratar la diabetes sin tratar el riesgo cardiovascular.","correccion":"La elección incluye fármacos con beneficio demostrado."},{"error":"Usar pioglitazona en insuficiencia cardíaca.","correccion":"Puede descompensar por retención de líquidos."},{"error":"No revisar el volumen con iSGLT2.","correccion":"El efecto diurético puede causar hipotensión o deshidratación."}],"comprueba":[{"pregunta":"¿Qué fármaco se prioriza en insuficiencia cardíaca?","respuesta":"Un iSGLT2."},{"pregunta":"¿Qué fármaco se prioriza en enfermedad aterosclerótica?","respuesta":"Un agonista GLP-1 con evidencia cardiovascular."},{"pregunta":"¿Qué se revisa con la polifarmacia?","respuesta":"Interacciones, volumen, hipoglucemia y adherencia."}],"resumen":["La diabetes con enfermedad cardiovascular requiere **beneficio demostrado**.","El iSGLT2 es prioritario en insuficiencia cardíaca.","El GLP-1 es prioritario en aterosclerosis.","La revisión integral reduce eventos y mejora la calidad de vida."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"}],"imagenes":[{"ubicacion":"Sección de insuficiencia cardíaca","descripcion":"Corazón con un iSGLT2 y una arteria coronaria con un GLP-1, ambos conectados a un plan integral.","alt":"Diabetes, enfermedad cardiovascular e insuficiencia cardíaca"}],"keywords":["diabetes enfermedad cardiovascular","isglt2 insuficiencia cardiaca","glp-1 aterosclerosis","manejo cardiovascular diabetes","diabetes e infarto","curso farmacoterapia diabetes"],"mapa":{"centro":"Corazón y diabetes","ramas":[{"titulo":"Aterosclerosis","icono":"Activity","nodos":["GLP-1","Estatina","Presión"]},{"titulo":"Insuficiencia cardíaca","icono":"Droplets","nodos":["iSGLT2","Diurético","Congestión"]},{"titulo":"Riesgo","icono":"ShieldCheck","nodos":["Tabaco","LDL","Peso"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Hipoglucemia","Volumen","Interacciones"]}]},"proceso":{"titulo":"Manejo integral del riesgo cardiovascular","intro":"","pasos":[{"titulo":"Clasificar el riesgo","detalle":"Enfermedad aterosclerótica, insuficiencia cardíaca o ambos.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Elegir fármaco","detalle":"GLP-1 para aterosclerosis, iSGLT2 para insuficiencia cardíaca.","icono":"Pill","evidencia":"Selección."},{"titulo":"Optimizar factores","detalle":"Presión, LDL, tabaco, peso y actividad.","icono":"Target","evidencia":"Plan."},{"titulo":"Revisar seguridad","detalle":"Volumen, hipoglucemia, interacciones y función renal.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Seguir","detalle":"Eventos, síntomas, adherencia y calidad de vida.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Coronaria e insuficiencia cardíaca","contexto":"Paciente de 70 años, diabetes tipo 2, infarto previo, insuficiencia cardíaca con fracción de eyección reducida, TFG 45 ml/min y HbA1c 8,2 %.","pregunta":"¿Qué combinación es más razonable?","opciones":[{"texto":"Solo metformina.","correcta":false,"retro":"No cubre el riesgo cardiovascular ni la insuficiencia cardíaca."},{"texto":"iSGLT2 por insuficiencia cardíaca y GLP-1 con evidencia cardiovascular, además de optimizar presión y LDL.","correcta":true,"retro":"La combinación cubre ambos riesgos; se revisan volumen, tolerancia y función renal."},{"texto":"Sulfonilurea y pioglitazona.","correcta":false,"retro":"La pioglitazona retiene líquidos y la sulfonilurea causa hipoglucemia; no son las mejores opciones."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Diabetes, enfermedad cardiovascular e insuficiencia cardíaca: manejo farmacológico integral$t$ AND deleted_at IS NULL
