  -- 10. Enfermedad renal crónica y diabetes: tamizaje, nefroprotección y ajuste de antidiabéticos
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La albuminuria que nadie miró","texto":"Un paciente con diabetes de 10 años tiene creatinina normal y nunca le han medido albuminuria. La TFG está en 58 ml/min y la albúmina/creatinina en 120 mg/g. La enfermedad renal ya empezó, pero el tratamiento puede retrasar la progresión. El tamizaje y la nefroprotección son parte del control de la diabetes."},"objetivos":["Aplicar el tamizaje de enfermedad renal en diabetes.","Interpretar TFG y albuminuria.","Seleccionar y ajustar antidiabéticos según la función renal.","Diseñar un plan de nefroprotección y seguimiento."],"conceptos":[{"icono":"Droplets","termino":"TFG","definicion":"Filtrado glomerular estimado; clasifica la enfermedad renal y guía el ajuste de fármacos."},{"icono":"AlertTriangle","termino":"Albuminuria","definicion":"Albúmina en orina ≥30 mg/g; marca daño renal y riesgo cardiovascular."},{"icono":"ShieldCheck","termino":"Nefroprotección","definicion":"Control de presión, iSGLT2, IECA/ARA-II y control glucémico para retrasar la progresión."},{"icono":"Pill","termino":"Ajuste","definicion":"Modificación de dosis o elección de fármacos según la TFG."}],"secciones":[{"titulo":"Tamizaje","parrafos":["La enfermedad renal crónica en diabetes se detecta con TFG y albuminuria. Se recomienda medir al menos una vez al año en todos los pacientes con diabetes y con más frecuencia si hay riesgo. La albuminuria debe confirmarse en dos de tres muestras en tres a seis meses, salvo causa evidente.","La TFG sola puede ser normal con albuminuria, y la albuminuria puede estar ausente con TFG baja. Por eso se miden las dos. La presión, el potasio y los lípidos también forman parte de la evaluación."]},{"titulo":"Nefroprotección","parrafos":["La nefroprotección incluye control de presión, iSGLT2, IECA o ARA-II cuando hay albuminuria e hipertensión, y control glucémico. Los iSGLT2 reducen la progresión renal y los eventos cardiovasculares. Algunos GLP-1 también han mostrado beneficio renal. La combinación puede ser razonable en alto riesgo.","Se revisan el potasio y la creatinina después de iniciar o ajustar IECA/ARA-II o iSGLT2. Una caída leve de TFG al inicio puede ser esperada. La educación sobre hidratación y días de enfermedad es importante."]},{"titulo":"Ajuste de antidiabéticos","parrafos":["La metformina se ajusta o suspende según la TFG: no iniciar con TFG <45, reducir con TFG 30-44 y contraindicar <30. Las sulfonilureas aumentan el riesgo de hipoglucemia en ERC. Los iDPP-4 tienen ajustes específicos; linagliptina no requiere ajuste. Los iSGLT2 pueden usarse con TFG baja según el fármaco y la indicación. La insulina requiere titulación cuidadosa.","El QF puede revisar cada fármaco, la dosis y la indicación. La polifarmacia en ERC aumenta el riesgo de interacciones y efectos adversos. La revisión periódica evita daño."]}],"errores":[{"error":"No medir albuminuria.","correccion":"La albuminuria detecta daño renal antes de la caída de la TFG."},{"error":"Mantener metformina con TFG <30.","correccion":"Está contraindicada; se suspende."},{"error":"No revisar potasio al iniciar IECA/ARA-II.","correccion":"La hiperpotasemia es un riesgo; se controla."}],"comprueba":[{"pregunta":"¿Con qué se tamiza la ERC en diabetes?","respuesta":"Con TFG y albuminuria."},{"pregunta":"¿Qué fármaco es clave para la nefroprotección?","respuesta":"Un iSGLT2, además del control de presión y glucosa."},{"pregunta":"¿Cuándo se contraindica la metformina?","respuesta":"Con TFG <30 ml/min."}],"resumen":["La ERC se detecta con **TFG y albuminuria**.","La nefroprotección incluye **iSGLT2 y control de presión**.","Los antidiabéticos se ajustan según la **TFG**.","El seguimiento renal es parte del control de la diabetes."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"}],"imagenes":[{"ubicacion":"Sección de tamizaje","descripcion":"Riñón con dos indicadores: TFG y albuminuria, y una flecha hacia iSGLT2 y control de presión.","alt":"Tamizaje y nefroprotección en diabetes"}],"keywords":["enfermedad renal crónica diabetes","albuminuria diabetes","isglt2 nefroprotección","metformina tfg","ajuste antidiabéticos erc","tamizaje renal diabetes","curso farmacoterapia diabetes"],"mapa":{"centro":"Riñón y diabetes","ramas":[{"titulo":"Tamizaje","icono":"Search","nodos":["TFG","Albuminuria","Presión"]},{"titulo":"Nefroprotección","icono":"ShieldCheck","nodos":["iSGLT2","IECA/ARA-II","Presión"]},{"titulo":"Ajuste","icono":"Pill","nodos":["Metformina","Sulfonilureas","Insulina"]},{"titulo":"Seguimiento","icono":"LineChart","nodos":["TFG","Albuminuria","Potasio"]}]},"proceso":{"titulo":"Manejo renal del paciente con diabetes","intro":"","pasos":[{"titulo":"Tamizar","detalle":"TFG y albuminuria al menos una vez al año.","icono":"Search","evidencia":"Resultados."},{"titulo":"Clasificar","detalle":"Estadio de ERC y riesgo cardiovascular.","icono":"LineChart","evidencia":"Clasificación."},{"titulo":"Nefroproteger","detalle":"Presión, iSGLT2, IECA/ARA-II y control glucémico.","icono":"ShieldCheck","evidencia":"Plan."},{"titulo":"Ajustar","detalle":"Revisar dosis y contraindicaciones según TFG.","icono":"Pill","evidencia":"Ajuste."},{"titulo":"Seguir","detalle":"TFG, albuminuria, potasio y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"TFG 58 y albuminuria 120","contexto":"Paciente con diabetes tipo 2, TFG 58 ml/min, albúmina/creatinina 120 mg/g, presión 142/88 mmHg, HbA1c 7,8 %. Toma metformina 1 g cada 12 horas.","pregunta":"¿Qué intervención es prioritaria?","opciones":[{"texto":"Solo aumentar metformina.","correcta":false,"retro":"La albuminuria y la presión requieren nefroprotección, no solo más metformina."},{"texto":"Iniciar o optimizar iSGLT2, controlar la presión y revisar la dosis de metformina.","correcta":true,"retro":"La albuminuria indica daño renal; el iSGLT2 y el control de presión son prioritarios."},{"texto":"Suspender metformina por la TFG.","correcta":false,"retro":"Con TFG 58 la metformina puede usarse; se revisa la dosis y el contexto."}]}}$j$::jsonb;
